return [
    'timisoara' => ['Sfaturi pentru șoferii din Timișoara', 'Vara, asfaltul încins și aerul condiționat pornit la maximum pun la încercare orice ciobitură — parchează la umbră până la evaluare și nu îndrepta jetul rece direct spre parbriz. Dacă faci des drumul spre Arad sau spre granița de vest, verifică parbrizul după fiecare tură lungă pe autostradă: un impact descoperit în prima zi are cele mai mari șanse să fie reparat. Pentru mașinile cu cameră pe parbriz, spune-ne de la început, ca oferta să includă și eventuala calibrare.'],
    'brasov' => ['Înainte de sezonul de schi', 'Mulți brașoveni își verifică anvelopele înainte de iarnă, dar uită de parbriz. O ciobitură mică, lăsată netratată până la primul ger pe drumul spre Poiana Brașov, are toate șansele să devină fisură. Dacă ai o mașină cu parbriz încălzit sau cu zonă încălzită pentru ștergătoare, trimite seria de șasiu: aceste variante nu se găsesc întotdeauna pe loc și e bine să fie comandate din timp.'],
    'ploiesti' => ['Când impactul apare pe A3', 'Pe autostradă, o piatră lovește la viteză mare, iar impactul are de obicei un centru adânc și fisuri scurte în jur. Lipește o bandă transparentă peste el până ajungi acasă și evită spălătoriile cu jet puternic. Dacă impactul e mai mic decât o monedă și departe de marginea parbrizului, de multe ori se poate repara fără să schimbi sticla — îți spunem din fotografie ce variantă e realistă.'],
    'craiova' => ['Mașini expuse la soare toată ziua', 'În Craiova, multe mașini stau parcate în soare în fața blocurilor din Rovine sau Craiovița Nouă. Sticla încinsă se dilată, iar o ciobitură veche poate „pleca” brusc în fisură când pornești aerul condiționat. Un parasolar și o răcire treptată a habitaclului ajută. Dacă fisura a depășit deja câțiva centimetri, înlocuirea e varianta sigură, iar oferta o primești înainte de orice programare.'],
    'suceava' => ['Drumuri lungi și distanțe mari în județ', 'Județul Suceava e întins, iar drumul până la un atelier poate dura. De aceea e util să trimiți din prima toate datele: marcă, model, an, serie de șasiu și o fotografie cu eticheta din colțul parbrizului. Așa verificăm varianta corectă de sticlă dintr-o singură discuție, iar tu afli dinainte dacă montajul se poate face mai aproape de tine.'],
    'cluj-napoca' => ['Parbriz și mașini noi cu multe dotări', 'În Cluj circulă multe mașini recente, cu cameră pentru menținerea benzii, senzor de ploaie și uneori afișaj pe parbriz (HUD). Toate acestea înseamnă coduri diferite de parbriz pentru același model. Cu seria de șasiu, verificăm exact varianta montată din fabrică, iar în ofertă vezi clar dacă e nevoie și de calibrarea camerei după montaj.'],
    'bacau' => ['Cum îți pregătești mașina pentru montaj', 'Înainte de programare, scoate din mașină obiectele de pe bord și din spatele oglinzii retrovizoare — camera de bord, suportul de telefon, eventualele abțibilduri. Dacă ai rovinieta sau un tag de taxare lipit pe parbriz, spune-ne: unele se pot muta, altele trebuie înlocuite. După montaj, lasă geamurile întredeschise câteva ore, ca presiunea din habitaclu să nu împingă parbrizul proaspăt lipit.'],
    'pitesti' => ['Flote și mașini de serviciu în Argeș', 'Piteștiul are multe firme cu mașini de serviciu și navetiști care fac zilnic drumul pe A1. Pentru firme, putem prelua mai multe cereri deodată — trimite lista de vehicule, iar oferta vine centralizat. Pentru mașinile personale, contează să spui de la început dacă ai cameră pe parbriz: la modelele recente, varianta de sticlă și eventuala calibrare schimbă prețul.'],
    'constanta' => ['Parbrizul după sezonul estival', 'După o vară cu nisip, sare și drumuri dese pe A2, parbrizul are adesea micro-zgârieturi care se văd mai ales noaptea, în lumina farurilor. Ștergătoarele uzate agravează problema. Dacă vizibilitatea e afectată, uneori soluția corectă e un parbriz nou; dacă zgârieturile sunt superficiale, îți spunem sincer că nu e cazul de înlocuire.'],
    'sibiu' => ['Iarna pe drumurile din Mărginimea Sibiului', 'Pe drumurile spre Păltiniș sau prin Mărginime, iarna, pietrișul și diferențele mari de temperatură sunt principalii dușmani ai parbrizului. Nu turna apă caldă pe sticla înghețată și nu folosi răzuitoare metalice. Dacă apare o fisură, montajul se programează de preferință într-un spațiu închis, unde adezivul se poate întări corect.'],
    'buzau' => ['Navetiști pe E85 și DN2', 'Buzăul e un oraș de trecere, cu mult trafic greu spre Moldova și spre București. Un parbriz lovit pe drum nu trebuie neapărat schimbat imediat — o ciobitură mică poate fi reparată, dacă e tratată repede. Trimite o fotografie de aproape, cu o monedă lângă impact pentru scară, și îți spunem ce variantă are sens.'],
    'iasi' => ['Drumurile spre Iași și traficul din oraș', 'Pe E583 dinspre Roman, pe DN24 spre Vaslui sau în traficul de pe Copou și Tătărași, parbrizul încasează des pietriș și praf. Dacă fisura e în câmpul vizual al șoferului, nu o amâna: la ITP poate fi o problemă, iar noaptea reflexiile farurilor obosesc vederea. Pentru o ofertă rapidă, trimite marca, modelul, anul și seria de șasiu.'],
    'arad' => ['Mașini aduse din străinătate', 'În zona Aradului circulă multe mașini cumpărate din vestul Europei, uneori cu dotări diferite de versiunile vândute în România — parbriz acustic, încălzit sau cu cameră. Seria de șasiu (VIN) ne ajută să identificăm exact varianta, indiferent de țara de proveniență. Așa eviți comanda unui parbriz care „pare la fel”, dar nu are suportul potrivit pentru senzori.'],
    'baia-mare' => ['Când e mai bine să aștepți o zi bună', 'În Maramureș, vremea se schimbă repede, iar ploaia sau frigul pot amâna un montaj la domiciliu. Dacă mașina îți e indispensabilă, cere de la început varianta în atelier, unde temperatura e controlată. Până la montaj, o bandă transparentă peste impact și un stil de condus mai atent pe drumurile de munte limitează extinderea fisurii.'],
    'galati' => ['Port, trafic greu și praf', 'În zona portului și a platformei industriale, camioanele ridică mult praf și pietriș, iar parbrizele mașinilor care circulă zilnic pe acolo se uzează mai repede. Ștergătoarele care trec peste nisip lasă zgârieturi fine, vizibile mai ales la răsărit și apus. Dacă vezi greu prin parbriz în aceste momente, merită o evaluare — uneori un parbriz nou e o chestiune de siguranță, nu de aspect.'],
    'braila' => ['Vânt de câmpie și montaj în siguranță', 'În Brăila, vântul puternic de câmpie aduce praf pe suprafața pe care se lipește parbrizul, iar asta poate afecta etanșarea. De aceea, în zilele cu vânt, recomandăm montajul în atelier. Dacă alegi montajul la adresă, caută un loc ferit — o curte sau o parcare între blocuri — și spune-ne în cerere unde stă mașina.'],
    'oradea' => ['Traficul spre Băile Felix și granița cu Ungaria', 'Pe drumul spre Băile Felix și pe cel spre vama Borș circulă zilnic mii de mașini, inclusiv camioane care ridică pietriș. Un impact apărut pe drum se vede uneori abia a doua zi, în lumina soarelui. Verifică parbrizul după drumurile lungi și, dacă găsești o ciobitură, trimite o fotografie: dacă e mică și recentă, poate fi reparată.'],
    'bistrita' => ['Ierni grele și drumuri de munte spre Tihuța', 'Iarna, între Bistrița și Pasul Tihuța, temperaturile scad mult sub zero, iar sticla se contractă. O fisură mică devine rapid una lungă dacă pornești dezghețarea la maximum. Încălzește treptat habitaclul și evită jetul de aer cald direct pe zona fisurată. Pentru mașinile cu parbriz încălzit, trimite seria de șasiu, ca varianta corectă să fie identificată din prima.'],
